        private string ResolveLibraryAgentOfflineResponse(string userPrompt, string instructions)
        {
            if (string.IsNullOrWhiteSpace(userPrompt))
            {
                return "Please connect to your preferred AI service for real-time queries.";
            }

            if (!PromptResponseRepository.TryGetResponse(_map, userPrompt, out var body))
            {
                body = "Please connect to your preferred AI service for real-time queries.";
            }

            var agentName = ResolveAgentNameFromInstructions(instructions);
            if (string.IsNullOrEmpty(agentName))
            {
                return body;
            }

            // Look up the per-agent real-time-AI styled response from the dedicated arrays.
            var requestKey = agentName + " :: " + userPrompt;
            for (int i = 0;
                 i < promptRequestForLibraryWithAgent.Length && i < promptResponseForLibraryWithAgent.Length;
                 i++)
            {
                if (string.Equals(
                        promptRequestForLibraryWithAgent[i],
                        requestKey,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return promptResponseForLibraryWithAgent[i];
                }
            }

            return $"<b>{agentName} Agent</b><br><i>Here is the response to your request:</i><br><br>" + body;
        }

        private static string ResolveAgentNameFromInstructions(string instructions)
        {
            if (string.IsNullOrWhiteSpace(instructions))
            {
                return string.Empty;
            }

            if (instructions.StartsWith("You are a learning", StringComparison.OrdinalIgnoreCase)) return "Learning";
            if (instructions.StartsWith("You are a career", StringComparison.OrdinalIgnoreCase)) return "Career";
            if (instructions.StartsWith("You are a planning", StringComparison.OrdinalIgnoreCase)) return "Planning";
            if (instructions.StartsWith("You are a prompt improvement", StringComparison.OrdinalIgnoreCase)) return "Prompt Improvement";
            if (instructions.StartsWith("You are a goals", StringComparison.OrdinalIgnoreCase)) return "Goals";

            return string.Empty;
        }

        private static string BuildAgentKey(string agentName, string promptContent)
        {
            var normalizedPrompt = (promptContent ?? string.Empty).Trim().ToLowerInvariant();
            return $"{(agentName ?? string.Empty).Trim().ToLowerInvariant()} :: {normalizedPrompt}";
        }

        private Dictionary<string, string> BuildLibraryAgentResponseMap()
        {
            var map = new Dictionary<string, string>(StringComparer.Ordinal);
            var items = _repo.PromptLibraryInfo.ToList();
            var responseByIndex = promptResponseforLibrary;

            for (int i = 0; i < items.Count && i < responseByIndex.Length; i++)
            {
                var item = items[i];
                if (item == null) continue;

                var topic = (item.Topic ?? string.Empty).Trim();
                if (string.IsNullOrEmpty(topic)) continue;

                if (!IsLibraryAgentTopic(topic)) continue;

                var body = responseByIndex[i] ?? string.Empty;
                var response = ComposeAgentResponse(topic, item.Title, body);
                var key = BuildAgentKey(topic, item.PromptContent);
                if (!map.ContainsKey(key))
                {
                    map[key] = response;
                }
            }

            return map;
        }

        private static bool IsLibraryAgentTopic(string topic)
        {
            switch (topic)
            {
                case "Learning":
                case "Career":
                case "Planning":
                case "Prompt Improvement":
                case "Goals":
                    return true;
                default:
                    return false;
            }
        }

        private static string ComposeAgentResponse(string agentName, string promptTitle, string body)
        {
            var titleSuffix = string.IsNullOrWhiteSpace(promptTitle)
                ? "your request"
                : $"\"{promptTitle}\"";

            return $"<b>{agentName} Agent</b><br>" +
                   $"<i>Here is the response to {titleSuffix}:</i><br><br>" +
                   body;
        }

